//
// Cross-checks for Curves.cs (Ed25519 + X25519 via BouncyCastle) against
// fixtures generated by Python's `cryptography` library using its
// libsodium-backed ed25519/x25519 implementations. If our values match
// `cryptography`, they'll match what an Apple TV (or pyatv) produces.

using AppleTVProtocol;

namespace AppleTVProtocol.Tests;

public class CurvesTests
{
    private static byte[] H(string hex) => Convert.FromHexString(hex);
    private static string Hex(byte[] b) => Convert.ToHexString(b).ToLowerInvariant();

    // ─── Ed25519 ───

    private const string Ed25519SeedHex   = "0102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f20";
    private const string Ed25519PubHex    = "79b5562e8fe654f94078b112e8a98ba7901f853ae695bed7e0e3910bad049664";
    private const string Ed25519MsgAscii  = "hello apple tv";
    private const string Ed25519SigHex    = "890ccf0408142ffd770e599b913d177441191da4e9832916dedb081f75062123be1bfa1c6966f5e9c2c601143d3b23c6f8fd7fa3eed8783bf1afcc77e3bdf20f";

    [Fact]
    public void Ed25519_PublicKey_DerivedFromSeed_MatchesFixture()
    {
        var priv = Ed25519PrivateKey.FromSeed(H(Ed25519SeedHex));
        Assert.Equal(Ed25519PubHex, Hex(priv.PublicKey.Bytes));
    }

    [Fact]
    public void Ed25519_Sign_IsDeterministic_AndMatchesFixture()
    {
        var priv = Ed25519PrivateKey.FromSeed(H(Ed25519SeedHex));
        var sig  = priv.Sign(System.Text.Encoding.ASCII.GetBytes(Ed25519MsgAscii));
        Assert.Equal(64, sig.Length);
        Assert.Equal(Ed25519SigHex, Hex(sig));
    }

    [Fact]
    public void Ed25519_Verify_AcceptsValidSignature()
    {
        var pub = Ed25519PublicKey.FromBytes(H(Ed25519PubHex));
        var ok  = pub.Verify(System.Text.Encoding.ASCII.GetBytes(Ed25519MsgAscii), H(Ed25519SigHex));
        Assert.True(ok);
    }

    [Fact]
    public void Ed25519_Verify_RejectsTamperedSignature()
    {
        var pub = Ed25519PublicKey.FromBytes(H(Ed25519PubHex));
        var sig = H(Ed25519SigHex);
        sig[0] ^= 0x01;
        var ok = pub.Verify(System.Text.Encoding.ASCII.GetBytes(Ed25519MsgAscii), sig);
        Assert.False(ok);
    }

    [Fact]
    public void Ed25519_Verify_RejectsTamperedMessage()
    {
        var pub = Ed25519PublicKey.FromBytes(H(Ed25519PubHex));
        var ok = pub.Verify(System.Text.Encoding.ASCII.GetBytes("hello apple tvX"), H(Ed25519SigHex));
        Assert.False(ok);
    }

    [Fact]
    public void Ed25519_Verify_RejectsWrongLengthSignature() =>
        Assert.False(Ed25519PublicKey.FromBytes(H(Ed25519PubHex)).Verify(new byte[1], new byte[63]));

    [Fact]
    public void Ed25519_PrivateKey_PreservesSeed()
    {
        var seed = H(Ed25519SeedHex);
        var priv = Ed25519PrivateKey.FromSeed(seed);
        Assert.Equal(Hex(seed), Hex(priv.Seed));
    }

    [Fact]
    public void Ed25519_KeyPair_Generate_ProducesUsableKey()
    {
        var (priv, pub) = Ed25519KeyPair.Generate();
        Assert.Equal(32, priv.Seed.Length);
        Assert.Equal(32, pub.Bytes.Length);
        var msg = "round-trip"u8.ToArray();
        Assert.True(pub.Verify(msg, priv.Sign(msg)));
    }

    [Fact]
    public void Ed25519_FromSeed_RejectsWrongLength()
    {
        Assert.Throws<ArgumentException>(() => Ed25519PrivateKey.FromSeed(new byte[31]));
        Assert.Throws<ArgumentException>(() => Ed25519PrivateKey.FromSeed(new byte[33]));
    }

    // ─── X25519 ───

    private const string X25519APrivHex = "101112131415161718191a1b1c1d1e1f202122232425262728292a2b2c2d2e2f";
    private const string X25519BPrivHex = "404142434445464748494a4b4c4d4e4f505152535455565758595a5b5c5d5e5f";
    private const string X25519APubHex  = "d89e3bad79437dbed9f843418304f460ff05c7fe81fe4a9577a804cb9367ff66";
    private const string X25519BPubHex  = "79a631eede1bf9c98f12032cdeadd0e7a079398fc786b88cc846ec89af85a51a";
    private const string X25519SharedHex= "0b7480daab7ce8926aaf208e30ef89c8403f7d00aa3db0428f914ead05c85e09";

    [Fact]
    public void X25519_PublicKey_DerivedFromPrivate_MatchesFixture()
    {
        var a = X25519PrivateKey.FromBytes(H(X25519APrivHex));
        var b = X25519PrivateKey.FromBytes(H(X25519BPrivHex));
        Assert.Equal(X25519APubHex, Hex(a.PublicKey.Bytes));
        Assert.Equal(X25519BPubHex, Hex(b.PublicKey.Bytes));
    }

    [Fact]
    public void X25519_Agree_IsSymmetricAndMatchesFixture()
    {
        var a    = X25519PrivateKey.FromBytes(H(X25519APrivHex));
        var b    = X25519PrivateKey.FromBytes(H(X25519BPrivHex));
        var aPub = X25519PublicKey.FromBytes(H(X25519APubHex));
        var bPub = X25519PublicKey.FromBytes(H(X25519BPubHex));

        var sharedAB = a.Agree(bPub);
        var sharedBA = b.Agree(aPub);

        Assert.Equal(X25519SharedHex, Hex(sharedAB));
        Assert.Equal(X25519SharedHex, Hex(sharedBA));
    }

    [Fact]
    public void X25519_FromBytes_RejectsWrongLength()
    {
        Assert.Throws<ArgumentException>(() => X25519PrivateKey.FromBytes(new byte[31]));
        Assert.Throws<ArgumentException>(() => X25519PublicKey.FromBytes(new byte[33]));
    }

    [Fact]
    public void X25519_KeyPair_Generate_RoundTrips()
    {
        var (aPriv, aPub) = X25519KeyPair.Generate();
        var (bPriv, bPub) = X25519KeyPair.Generate();
        var sAB = aPriv.Agree(bPub);
        var sBA = bPriv.Agree(aPub);
        Assert.Equal(32, sAB.Length);
        Assert.Equal(Hex(sAB), Hex(sBA));
    }
}
